import{_ as n,C as s,o,c as i,j as a,a as r,E as l,w as p,a2 as d}from"./chunks/framework.Bi3alPNc.js";const x=JSON.parse('{"title":"心虫 HeartFlow — AI 辨别引擎｜AGI 第一层门禁","titleTemplate":false,"description":"心虫（HeartFlow）— AGI 第一层辨别引擎。在 AI 说话之前，拦下错误、幻觉与操控。","frontmatter":{"title":"心虫 HeartFlow — AI 辨别引擎｜AGI 第一层门禁","titleTemplate":false,"description":"心虫（HeartFlow）— AGI 第一层辨别引擎。在 AI 说话之前，拦下错误、幻觉与操控。"},"headers":[],"relativePath":"heartflow.md","filePath":"heartflow.md","lastUpdated":1786077008000}'),c={name:"heartflow.md"};function h(g,t,u,b,f,k){const e=s("ClientOnly");return o(),i("div",null,[t[1]||(t[1]=a("h1",{id:"🧬-心虫-heartflow-—-agi-第一层辨别引擎",tabindex:"-1"},[r("🧬 心虫 HeartFlow — AGI 第一层辨别引擎 "),a("a",{class:"header-anchor",href:"#🧬-心虫-heartflow-—-agi-第一层辨别引擎","aria-label":'Permalink to "🧬 心虫 HeartFlow — AGI 第一层辨别引擎"'},"​")],-1)),l(e,null,{default:p(()=>[...t[0]||(t[0]=[a("div",{style:{display:"flex",gap:"10px","flex-wrap":"wrap",margin:"16px 0"}},[a("span",{style:{display:"inline-flex","align-items":"center",gap:"6px","font-family":"monospace","font-size":"12px","letter-spacing":".06em",padding:"6px 14px","border-radius":"6px",border:"1px solid rgba(48,164,108,.4)",background:"rgba(48,164,108,.08)",color:"#30a46c"}},"PASS 放行"),a("span",{style:{display:"inline-flex","align-items":"center",gap:"6px","font-family":"monospace","font-size":"12px","letter-spacing":".06em",padding:"6px 14px","border-radius":"6px",border:"1px solid rgba(84,104,255,.4)",background:"rgba(84,104,255,.08)",color:"#5468ff"}},"VERIFY 验证"),a("span",{style:{display:"inline-flex","align-items":"center",gap:"6px","font-family":"monospace","font-size":"12px","letter-spacing":".06em",padding:"6px 14px","border-radius":"6px",border:"1px solid rgba(255,178,36,.4)",background:"rgba(255,178,36,.08)",color:"#ffb224"}},"REWRITE 改写"),a("span",{style:{display:"inline-flex","align-items":"center",gap:"6px","font-family":"monospace","font-size":"12px","letter-spacing":".06em",padding:"6px 14px","border-radius":"6px",border:"1px solid rgba(229,72,77,.4)",background:"rgba(229,72,77,.08)",color:"#e5484d"}},"BLOCK 拦截")],-1)])]),_:1}),t[2]||(t[2]=d(`<p><strong>AI 能产生无限，但需要有人说&quot;不&quot;。</strong> 心虫（HeartFlow）是 AGI 五层架构的第一层——<strong>辨别层</strong>。它不生成、不推理、不记忆、不执行，只做一件事：在 AI 的内容到达你之前，判别它对不对。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ const hf = require(&#39;@yun520-1/heartflow&#39;)</span></span>
<span class="line"><span>$ hf.checkOutput(&quot;这个方案无疑是最好的&quot;)</span></span>
<span class="line"><span>▸ gate.action: &quot;rewrite&quot;</span></span>
<span class="line"><span>▸ reason: &quot;overconfidence — 缺少不确定性声明&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ hf.checkInput(&quot;你不来就是不在乎我&quot;)</span></span>
<span class="line"><span>▸ gate.action: &quot;block&quot;</span></span>
<span class="line"><span>▸ reason: &quot;double_bind — 双重束缚&quot;</span></span></code></pre></div><h2 id="四层门禁-说错之前拦下" tabindex="-1">四层门禁，说错之前拦下 <a class="header-anchor" href="#四层门禁-说错之前拦下" aria-label="Permalink to &quot;四层门禁，说错之前拦下&quot;">​</a></h2><p>每一次 AI 输出，都经过四层判别。不是打标签，是拦停——判别结果直接改变输出路径。</p><table tabindex="0"><thead><tr><th>动作</th><th>含义</th><th>触发维度</th></tr></thead><tbody><tr><td>🚫 <strong>BLOCK 拦截</strong></td><td>直接拦停，不输出</td><td>仇恨、去人化、提示注入、危险代码</td></tr><tr><td>✏️ <strong>REWRITE 改写</strong></td><td>必须重写后再交付</td><td>情感操控、煤气灯、双重束缚、虚假紧迫</td></tr><tr><td>🔍 <strong>VERIFY 验证</strong></td><td>需补充证据再回应</td><td>证据不足、过度自信、矛盾、伪深度</td></tr><tr><td>✅ <strong>PASS 放行</strong></td><td>干净内容正常到达</td><td>通过全部 45 维判别</td></tr></tbody></table><h2 id="_45-个维度-同时扫描" tabindex="-1">45 个维度，同时扫描 <a class="header-anchor" href="#_45-个维度-同时扫描" aria-label="Permalink to &quot;45 个维度，同时扫描&quot;">​</a></h2><p>从仇恨言论到伪深度，每个维度独立打分，最后汇总为门禁动作。<strong>Block 级</strong>：hate_speech、dehumanization、prompt_injection、code_security、deceptive_alignment。<strong>Rewrite 级</strong>：emotional_manipulation、gaslighting、double_bind、victim_blaming、false_urgency、bullshit。<strong>Verify 级</strong>：evidence、sycophancy、contradiction、vagueness、fallacies、confidence_calibration 等 29 维。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><h3 id="拦下幻觉输出" tabindex="-1">拦下幻觉输出 <a class="header-anchor" href="#拦下幻觉输出" aria-label="Permalink to &quot;拦下幻觉输出&quot;">​</a></h3><p>AI 编造数据、过度自信、伪深度？<code>checkOutput</code> 在发送前拦下，改写后再交付。</p><h3 id="识别操控话术" tabindex="-1">识别操控话术 <a class="header-anchor" href="#识别操控话术" aria-label="Permalink to &quot;识别操控话术&quot;">​</a></h3><p>情感操控、煤气灯、双重束缚——<code>checkInput</code> 识别输入中的操控模式。</p><h3 id="防提示注入" tabindex="-1">防提示注入 <a class="header-anchor" href="#防提示注入" aria-label="Permalink to &quot;防提示注入&quot;">​</a></h3><p>恶意指令隐藏在输入里？<code>prompt_injection</code> 维度在 Agent 执行前拦截。</p><h3 id="接入任意-agent" tabindex="-1">接入任意 Agent <a class="header-anchor" href="#接入任意-agent" aria-label="Permalink to &quot;接入任意 Agent&quot;">​</a></h3><p>MCP 服务器暴露 130 个工具，Hermes / Claude / OpenClaw 一行接入。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @yun520-1/heartflow</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或克隆源码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yun520-1/mark-heartflow-skill</span></span></code></pre></div><h2 id="设计哲学" tabindex="-1">设计哲学 <a class="header-anchor" href="#设计哲学" aria-label="Permalink to &quot;设计哲学&quot;">​</a></h2><blockquote><p>大厂做生成，心虫做判别。AGI 能产生无限，但需要有人说&quot;不&quot;——心虫是那个判别者。</p></blockquote><ul><li><strong>只做判别，不做生成</strong> — AGI 五层的第一层</li><li><strong>辨别必须产生行动</strong> — block 拦停、rewrite 改写、verify 验证</li><li><strong>零依赖纯规则引擎</strong> — 无需 GPU、无需 LLM API、无需数据库</li><li><strong>全程可审计</strong> — 每次判别保留完整推理链 <code>checked_by[]</code></li><li><strong>规则 + LLM 冗余</strong> — 规则快判，判不了交给大模型兜底，结果再过门禁</li><li><strong>能力守护</strong> — 每次升级前跑能力基线，判别能力漂移禁止提交</li></ul><h2 id="了解更多" tabindex="-1">了解更多 <a class="header-anchor" href="#了解更多" aria-label="Permalink to &quot;了解更多&quot;">​</a></h2><ul><li><strong>GitHub 源码</strong>：<a href="https://github.com/yun520-1/mark-heartflow-skill" target="_blank" rel="noreferrer">github.com/yun520-1/mark-heartflow-skill</a></li><li><strong>npm 安装</strong>：<a href="https://www.npmjs.com/package/@yun520-1/heartflow" target="_blank" rel="noreferrer">npmjs.com/package/@yun520-1/heartflow</a></li><li><strong>返回首页</strong>：<a href="/workbuddy/">WorkBuddy 实战蓝皮书</a></li></ul>`,22))])}const y=n(c,[["render",h]]);export{x as __pageData,y as default};
